/// the version surface this binary reports.
///
/// `display` is what `--version` prints: the semantic version, plus the commit
/// the binary was built from when that information was available at build time
/// (`GitProvenance` is generated by the `GitMetadataPlugin` build tool plugin).
enum AppVersion {
    /// the release version. the single place the number is written — bump here.
    static let semantic = "3.2.0"

    /// `3.2.0` from a source tarball or a git-less machine; `3.2.0+abc1234`
    /// from a clean checkout; `3.2.0+abc1234.dirty` when the working tree had
    /// local changes at build time. the `+…` suffix is semver build metadata.
    static var display: String {
        guard let shortCommit = GitProvenance.shortCommitHash else { return semantic }
        var version = "\(semantic)+\(shortCommit)"
        if GitProvenance.isDirty { version += ".dirty" }
        return version
    }
}